// 对象或数组整体跳过，其内部成员不单独检查。
func checkContextValueTypes(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	// UseNumber：数字按 json.Number 原样保留而不转 float64，使超出浮点范围
