		keyTok, err := dec.Token()
		if err != nil {
			return nil // 语法错误留给严格解码的报错
		}
		key, _ := keyTok.(string)
		var value any
		if err := dec.Decode(&value); err != nil {
			return nil // 语法错误留给严格解码的报错
		}
		if _, ok := value.(string); !ok {
			return fmt.Errorf("%s: value must be a string", appendFieldPath("context", key))
		}
	}
	return nil
}

